from __future__ import annotations
from itertools import product
from typing import Callable, List, Optional, Sequence


def all_functions(domain: Sequence[int], codomain: Sequence[int]
                  ) -> List[Callable[[int], int]]:
    """Enumerate every function domain -> codomain as a lookup closure."""
    funcs: List[Callable[[int], int]] = []
    for values in product(codomain, repeat=len(domain)):
        table = dict(zip(domain, values))
        funcs.append(lambda x, _t=table: _t[x])
    return funcs


def is_point_surjective(g: Callable[[int], Callable[[int], int]],
                        A: Sequence[int], B: Sequence[int]) -> bool:
    """Every h : A -> B is named by some a in A, i.e. g(a) = h."""
    named = {tuple(g(a)(x) for x in A) for a in A}
    return all(tuple(h(x) for x in A) in named
               for h in all_functions(A, B))


def lawvere_fixed_point(g: Callable[[int], Callable[[int], int]],
                        A: Sequence[int], t: Callable[[int], int]
                        ) -> Optional[int]:
    """Diagonal construction: h(x)=t(g(x)(x)); name it by a; return g(a)(a)."""
    diagonal = tuple(t(g(x)(x)) for x in A)
    for a in A:
        if tuple(g(a)(x) for x in A) == diagonal:
            return g(a)(a)
    return None


if __name__ == "__main__":
    S = [0]  # nonempty subsingleton: a provably complete self-model
    g = lambda a: (lambda _x: 0)
    print("point-surjective (complete):", is_point_surjective(g, S, S))
    for name, t in [("identity", lambda x: x), ("const", lambda _x: 0)]:
        fp = lawvere_fixed_point(g, S, t)
        print(f"{name}: fixed point {fp}, verified {t(fp) == fp}")

from __future__ import annotations
from typing import Callable, Dict, List


def iterate(t: Callable[[int], int], b: int, n: int) -> int:
    for _ in range(n):
        b = t(b)
    return b


def orbit(t: Callable[[int], int], b: int, horizon: int) -> List[int]:
    """Forward orbit t^0(b), t^1(b), ..., t^horizon(b)."""
    return [iterate(t, b, n) for n in range(horizon + 1)]


def is_strange_loop(t: Callable[[int], int], b: int, horizon: int) -> bool:
    """A Lawvere fixed point is invariant under every iterate."""
    return all(v == b for v in orbit(t, b, horizon))


if __name__ == "__main__":
    table: Dict[int, int] = {0: 1, 1: 2, 2: 2}  # fixed point at 2
    t = lambda x: table[x]
    print("orbit from 2:", orbit(t, 2, 6))
    print("strange loop (period-one):", is_strange_loop(t, 2, 6))
    print("orbit from 0 converges:", orbit(t, 0, 6))

