"""Hasse diagram of the conscious-state lattice inside the powerset."""
from __future__ import annotations
from itertools import product
from typing import Callable, FrozenSet, List
import matplotlib.pyplot as plt


def powerset(ground: List[int]) -> List[FrozenSet[int]]:
    return [frozenset(g for g, b in zip(ground, c) if b)
            for c in product([0, 1], repeat=len(ground))]


def main() -> None:
    ground = [1, 2, 3]
    lattice = powerset(ground)

    def refine(s: FrozenSet[int]) -> FrozenSet[int]:
        out = set(s)
        if 2 in s:
            out.add(1)
        return frozenset(out)

    conscious = {s for s in lattice if refine(s) == s}
    pos = {}
    for s in lattice:
        pos[s] = (sum(s) - 2 * len(s), len(s))
    plt.figure(figsize=(8, 6))
    for a in lattice:
        for b in lattice:
            if a < b and len(b) == len(a) + 1:
                plt.plot([pos[a][0], pos[b][0]], [pos[a][1], pos[b][1]],
                         color="gray", alpha=0.4, zorder=1)
    for s in lattice:
        col = "crimson" if s in conscious else "lightsteelblue"
        plt.scatter(*pos[s], s=600, color=col, zorder=2, edgecolors="black")
        plt.text(pos[s][0], pos[s][1], "{" + ",".join(map(str, sorted(s))) + "}",
                 ha="center", va="center", fontsize=8)
    plt.title("Conscious (self-consistent) states in red form a complete lattice")
    plt.axis("off")
    plt.tight_layout()
    plt.savefig("conscious_lattice.png", dpi=150)
    print("saved conscious_lattice.png")


if __name__ == "__main__":
    main()

